#!/usr/bin/env node
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { applyHostFlag } from "./config.js";
import { createMcpServer } from "./server.js";
applyHostFlag();
const server = createMcpServer();
await server.connect(new StdioServerTransport());

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { CURSOR_PATTERN, defaultPushHost, ENVIRONMENTS, ID_PATTERN, IMAGE_DIGEST_PATTERN, KEY_PATTERN, LOGIN_CAPABILITIES, PLAN_HASH_PATTERN, RUN_ACTIONS, } from "./config.js";
import { EXECUTION_SCHEMA, MAX_DURATION_SECONDS, MIN_DURATION_SECONDS } from "./execution.js";
import { deployTool, evidenceTool, logsTool, runsTool, runTool, } from "./control.js";
import { keychainStorage } from "./keychain.js";
import { deviceLogin } from "./login.js";
import { pushTool } from "./push.js";
import { emptyState, fileStateStore, } from "./state.js";
function allowlistText(allowlist) {
    const lines = [
        `draftId: ${allowlist.draftId}`,
        `version: ${allowlist.version}`,
    ];
    if (allowlist.planHash !== undefined)
        lines.push(`planHash: ${allowlist.planHash}`);
    if (allowlist.validation !== undefined) {
        lines.push("validation:");
        for (const entry of allowlist.validation) {
            lines.push(`  - ruleId ${entry.ruleId} at ${entry.fieldPath}`);
        }
    }
    if (allowlist.connections !== undefined && allowlist.connections.length > 0) {
        lines.push("connections:");
        for (const connection of allowlist.connections) {
            lines.push(`  - ${connection.connectorId}: ${connection.status}`);
        }
    }
    if (allowlist.consoleUrl !== undefined) {
        lines.push(`consoleUrl: ${allowlist.consoleUrl}`);
    }
    return lines.join("\n");
}
function errorText(lines) {
    return { content: [{ type: "text", text: lines.join("\n") }], isError: true };
}
function okText(lines) {
    return { content: [{ type: "text", text: lines.join("\n") }] };
}
function strict(shape) {
    return z.object(shape).strict();
}
export function createMcpServer(deps = {}) {
    const server = new McpServer({ name: "cager", version: "0.2.0" }, {
        instructions: "Push a draft to a Cager deployment, request its release, start and control runs, and read " +
            "status, lifecycle events and signed evidence. Pushing and running are separate logins: " +
            "cager_login with draft:push to push, and with the run, release or read capabilities to deploy, " +
            "run and read. Identities, states, counts and digests only; no output or log text.",
    });
    const storage = deps.storage ?? keychainStorage();
    server.registerTool("cager_login", {
        title: "Cager device login",
        description: "Sign the coding agent in to a Cager push host by RFC 8628 device authorization for " +
            "one explicit capability set. draft:push is its own consent (push only). release:request, run:start, " +
            "run:control, run:read and evidence:read form control consents, which cannot be mixed with draft:push; " +
            "ask for the smallest set the task needs (a read-only login asks for run:read and evidence:read only). " +
            "Returns the console URL and the one-time user code for the human; the minted token and its DPoP key " +
            "are stored in the OS keychain per host, audience and consent, and never returned. Re-run while pending " +
            "to keep polling.",
        inputSchema: strict({
            capabilities: z
                .array(z.enum(LOGIN_CAPABILITIES))
                .min(1)
                .max(LOGIN_CAPABILITIES.length)
                .describe("The capability set the human is asked to approve. Default: draft:push.")
                .optional(),
            host: z
                .string()
                .describe(`The bare push host to log in against (default ${defaultPushHost()}).`)
                .optional(),
            agent_name: z
                .string()
                .min(1)
                .max(64)
                .describe("The agent name the consent screen shows the human.")
                .optional(),
            wait_seconds: z
                .number()
                .int()
                .min(1)
                .max(600)
                .describe("How long this call polls the token endpoint before returning pending.")
                .default(600),
        }),
    }, async (input) => {
        const host = typeof input.host === "string" && input.host.length > 0 ? input.host : defaultPushHost();
        const result = await deviceLogin(storage, {
            capabilities: input.capabilities,
            pushHost: host,
            agentName: input.agent_name ?? "Cager agent",
            waitSeconds: input.wait_seconds ?? undefined,
            fetchImpl: deps.fetchImpl,
            scheme: deps.scheme,
        });
        const lines = [`cager_login: ${result.status}`, `scope: ${result.identifier}`];
        if (result.keyThumbprint !== undefined) {
            lines.push(`DPoP key thumbprint: ${result.keyThumbprint}`);
        }
        if (result.grantId !== undefined) {
            lines.push(`grant_id: ${result.grantId} (pass it to a control tool to name this consent)`);
        }
        if (result.verificationUriComplete !== undefined) {
            lines.push(`Open this URL to approve, while signed in to the Cager console: ${result.verificationUriComplete}`);
        }
        else if (result.verificationUri !== undefined) {
            lines.push(`Open this URL and enter the code, while signed in: ${result.verificationUri}`);
        }
        if (result.verificationExpiresAt !== undefined) {
            lines.push(`The device code expires at ${result.verificationExpiresAt}.`);
        }
        if (result.detail !== undefined)
            lines.push(result.detail);
        return result.status === "approved" ? okText(lines) : errorText(lines);
    });
    server.registerTool("cager_push", {
        title: "Cager push",
        description: "Push one source directory to a Cager deployment as one content-addressed source bundle with the " +
            "closed manifest, or one prebuilt image by immutable digest (image_digest, exclusive " +
            "with path). Needs the draft:push login. The bundle is tar; every accepted push mints a new immutable draft " +
            "version. The same idempotency key and digest replays the recorded answer; the same key with a " +
            "different request (source, target, manifest or execution declaration) is refused. An image push names " +
            "application_id, environment and the execution declaration, and succeeds only when the answer carries " +
            "the planHash; cager_deploy presents that exact draft, version and planHash. The answer is the D5 " +
            "allowlist: opaque draft id, version, planHash, validation by " +
            "rule id and field path, connections by connector id with a coarse status, and the console URL for the human.",
        inputSchema: strict({
            path: z
                .string()
                .min(1)
                .describe("The absolute or relative path of the source directory to push. Exclusive with image_digest: " +
                "give exactly one of the two.")
                .optional(),
            image_digest: z
                .string()
                .regex(IMAGE_DIGEST_PATTERN)
                .describe("One prebuilt OCI image by immutable digest, repository@sha256:<64 hex>; a tag is refused. " +
                "Exclusive with path. The platform verifies the image's signature before it can run.")
                .optional(),
            name: z.string().min(1).max(120).describe("The draft's display name.").optional(),
            draft_id: z
                .string()
                .min(1)
                .describe("A draftId an earlier push answered, to mint the next version parented to it.")
                .optional(),
            manifest: z
                .record(z.unknown())
                .describe("The closed manifest: entrypoint, runtime, tools by connectorId, egress_hosts, suggested_schedule. " +
                "Requests only, never grants; unknown keys are refused.")
                .optional(),
            application_id: z
                .string()
                .regex(ID_PATTERN)
                .describe("The registered application this push targets. Required with image_digest, no default; the " +
                "display name and the image never select it.")
                .optional(),
            environment: z
                .enum(ENVIRONMENTS)
                .describe("The registered environment this push targets. Required with image_digest, no default.")
                .optional(),
            execution: z
                .object({
                schema: z.literal(EXECUTION_SCHEMA),
                agents: z
                    .array(z
                    .object({
                    agentId: z.string().describe("Lowercase letters, digits and dashes."),
                    argv: z
                        .array(z.string())
                        .describe("An exec argv, never a shell line: argv[0] an absolute path, every other element a plain token."),
                    maxDurationSeconds: z
                        .number()
                        .int()
                        .min(MIN_DURATION_SECONDS)
                        .max(MAX_DURATION_SECONDS)
                        .describe("Seconds, 1 to 3600, explicit, no default."),
                })
                    .strict())
                    .min(1)
                    .describe("Sorted by agentId and unique."),
            })
                .strict()
                .describe(`The execution declaration ${EXECUTION_SCHEMA}: per agent the exact argv and the run's maximum ` +
                "duration. Required with image_digest and refused without it. A proposal only; acceptance is a " +
                "separate release decision.")
                .optional(),
            idempotency_key: z.string().min(1).max(200).describe("A client-generated idempotency key.").optional(),
            host: z.string().describe(`The push host (default ${defaultPushHost()}).`).optional(),
        }),
    }, async (input) => {
        const host = typeof input.host === "string" && input.host.length > 0 ? input.host : defaultPushHost();
        const toolInput = {
            path: input.path,
            imageDigest: input.image_digest,
            name: input.name,
            draftId: input.draft_id,
            manifest: input.manifest,
            applicationId: input.application_id,
            environment: input.environment,
            execution: input.execution,
            idempotencyKey: input.idempotency_key,
        };
        const result = await pushTool(toolInput, {
            pushHost: host,
            storage,
            stateStore: deps.stateStore,
            fetchImpl: deps.fetchImpl,
            scheme: deps.scheme,
        });
        if (result.status === "refused") {
            const lines = [`cager_push refused: ${result.reason}`];
            if (result.status_code !== undefined)
                lines.push(`status: ${result.status_code}`);
            if (result.field !== undefined)
                lines.push(`field: ${result.field}`);
            lines.push(result.detail);
            return errorText(lines);
        }
        const lines = [
            `cager_push ${result.status}`,
            `bundle digest: ${result.digest}`,
            `idempotency key: ${result.idempotencyKey}`,
            "",
            allowlistText(result.allowlist),
        ];
        return okText(lines);
    });
    server.registerTool("cager_status", {
        title: "Cager status",
